        report_data = self.generator.generate_report(
            analysis_results=results_snapshot,
            metadata=metadata,
            debug_data=report_context,
            masked_image_path=masked_img_path,
            logo_path=logo_path
        )

        return report_data

    finally:
        if should_close:
            db.close()

